test('invoiceTotals sums line totals for a single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 3 * 8500);
  assert.equal(totals.total, 3 * 8500);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expected = (2 * 8500) + (3 * 9500);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals calculates correctly with multiple varied items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const expected = (5 * 8500) + (1 * 120000) + (100 * 50);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals calculates discount correctly for a single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500;
  const discount = subtotal * 10 / 100;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.total, subtotal - discount);
});

test('invoiceTotals sums discounts for multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const sub1 = 2 * 8500;
  const sub2 = 3 * 9500;
  const disc1 = sub1 * 10 / 100;
  const disc2 = sub2 * 20 / 100;
  assert.equal(totals.subtotal, sub1 + sub2);
  assert.equal(totals.discount, disc1 + disc2);
  assert.equal(totals.total, (sub1 + sub2) - (disc1 + disc2));
});

